const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.join(__dirname,process.argv.includes('--tree')?'skill-tree-20261006':'creature-scale-20261006'),api=require(path.join(root,'creature-scale.js')),html=fs.readFileSync(path.join(root,'index.html'),'utf8'),results=[];
const check=(name,fn)=>{fn();results.push(name)};
for(const m of html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g))new vm.Script(m[1]);
check('24 ordinary species assigned unique physical tiers',()=>{const keys=Object.values(api.species).flat();assert.equal(new Set(keys).size,keys.length);assert.equal(keys.length,24)});
check('tiny < small < ordinary < large < boss in both views',()=>{const keys=['tiny','small','standard','large','boss'];for(let i=1;i<keys.length;i++){assert.ok(api.tiers[keys[i]].world>api.tiers[keys[i-1]].world);assert.ok(api.tiers[keys[i]].cinema>api.tiers[keys[i-1]].cinema)}});
check('human and jelly protagonist proportions unchanged',()=>{assert.deepEqual(api.get({cls:'mage',human:true}),{tier:'party',world:1.82,cinema:1/3,foot:1,bar:.86});assert.equal(api.get({cls:'warrior'}).world,1.18);assert.equal(api.figure({cls:'mage'}),'')});
check('all explicit bosses retain original size even if named slime or humanoid',()=>{for(const kind of ['slime','goat','odin','star_crab','babel_beast'])assert.equal(api.get({kind,boss:true}).world,2.9)});
check('recruiting creatures does not alter their species size',()=>{for(const kind of Object.values(api.species).flat())assert.deepEqual(api.get({kind,team:'enemy'}),api.get({kind,team:'ally'}))});
check('reinforcement aliases inherit species artwork size',()=>{assert.equal(api.get({kind:'bd_selena_0_1'},{art:'mon_slime'}).tier,'tiny');assert.equal(api.get({kind:'bd_grom_0_0'},{art:'mon_golem'}).tier,'large')});
check('unknown creatures use ordinary scale, never implicit boss scale',()=>{assert.equal(api.get({kind:'future'}).cinema,1/3)});
check('cinematic centers remain at 26% and floor does not move',()=>{for(const t of Object.values(api.tiers))assert.ok(Math.abs((26-19*t.cinema)+38*t.cinema/2-26)<1e-8);const css=fs.readFileSync(path.join(root,'creature-scale.css'),'utf8');assert.ok(!/\.dfig\[.*\]\{[^}]*\bbottom:/.test(css))});
check('body, obstruction ghost and bar use common geometry scale',()=>{assert.match(html,/u\.sc = sc/);assert.match(html,/u\.bar\.position\.y = u\.sc/);assert.match(html,/u\.ghost\.scale\.y = u\.sc/);assert.match(html,/u\.tri\.scale\.setScalar\(bodySize\.foot\)/)});
check('size module is pure display, no stat/save mutation',()=>{const source=fs.readFileSync(path.join(root,'creature-scale.js'),'utf8');assert.ok(!/localStorage|hp\s*=|atk\s*=|damage|mp\s*=/.test(source))});
console.log(JSON.stringify({passed:results.length,results},null,2));
const qa=`<script>artReady.then(()=>{
 const nav=document.createElement('nav');nav.id='scaleQA';nav.style='position:fixed;top:6px;left:6px;right:6px;z-index:230;background:#142631;color:white;font:11px sans-serif;padding:6px';nav.innerHTML='<button id="cqLoad">比例實景</button><select id="cqKind" aria-label="比較魔物">'+['slime','shroom','wolf','imp','golem','rguard','goat'].map(k=>'<option value="'+k+'">'+MONS[k].nm+'</option>').join('')+'</select><button id="cqDuel">戰鬥比較</button><button id="cqReport">比例數值</button><button id="cqHide">收起測試</button><output id="cqOutput"></output>';document.body.appendChild(nav);let hero,creatures={};
 const report=()=>document.querySelector('#cqOutput').textContent=JSON.stringify({edition:document.documentElement.dataset.creatureEdition,hero:hero&&{world:hero.sc},creatures:Object.entries(creatures).map(([kind,u])=>({kind,size:CreatureScale.get(u,MONS[kind]),world:u.sc,bar:u.bar.scale.x,ring:u.ring.scale.x,hp:u.hp})),phase:G.phase});
 document.querySelector('#cqLoad').onclick=()=>{setup.picks=[{cls:'warrior',name:'盾盾',col:5,el:'地',lead:true},{cls:'support',name:'艾莉',sex:'f',el:'光'}];for(const cls of ['warrior','support'])ROSTER[cls]={lv:12,exp:0,adv:true};curNode=NODES.find(n=>n.id==='1-王');buildBattle();chooseZone(ZONES[0]);for(const u of units){scene.remove(u.grp)}units=[];G.party=[];
  for(const [cls,x]of [['warrior',4],['support',6]]){const u=makeUnit({team:'hero',cls,human:cls==='support',sex:'f',col:5,name:cls==='support'?'艾莉':'盾盾',lv:12,el:'光',st:statsFor(cls,12,true),basic:'strike',skills:[],x,z:8,face:[0,-1]});G.party.push(u);if(cls==='support')hero=u;}
  const spots=[['slime',3,7],['shroom',7,7],['wolf',3,5],['imp',7,5],['golem',4,3],['rguard',7,3],['goat',5,1]];creatures={};for(const [kind,x,z]of spots){const m=MONS[kind],u=makeUnit({team:'enemy',kind,name:m.nm,boss:!!m.boss,lv:m.lv,el:m.el,st:m.st,basic:m.basic,skills:[],x,z,face:[0,1]});creatures[kind]=u;}
  G.phase='battle';mode='busy';$('#deploy').hidden=$('#bottom').hidden=$('#order').hidden=true;$('#tools').hidden=false;focusOn({pos:tileCenter(5,5)},1.1);report();};
 document.querySelector('#cqDuel').onclick=async()=>{const d=creatures[document.querySelector('#cqKind').value];if(!hero||!d)return;try{duelQA.setDuel(true);await duelQA.scene(hero,d,SK.strike,[d]);report()}catch(e){document.querySelector('#cqOutput').textContent=e.stack;console.error(e)}};
 document.querySelector('#cqReport').onclick=report;document.querySelector('#cqHide').onclick=()=>nav.style.display='none';
});</script>`;
if(process.argv.includes('--serve'))require('node:http').createServer((req,res)=>{const url=new URL(req.url,'http://localhost'),file=path.resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if(!file.startsWith(root+path.sep)||!fs.existsSync(file)){res.writeHead(404).end();return;}const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.jpg':'image/jpeg','.png':'image/png','.webp':'image/webp'};res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'});if(file.endsWith('index.html')&&url.searchParams.has('scaleqa')){let content=fs.readFileSync(file,'utf8');if(url.searchParams.has('photo'))content=content.replace('    await W8(150);','    await W8(150); await new Promise(()=>{});');res.end(content.replace('</body>',qa+'</body>'));}else fs.createReadStream(file).pipe(res);}).listen(4185,'127.0.0.1',()=>console.log('Creature QA ready:4185'));
